import { TRPCError } from "@trpc/server";
import type { CreateExpressContextOptions } from "@trpc/server/adapters/express";
import { z } from "zod";
import { ENV } from "./_core/env";
import { canonicalVerifiedRole, resolveVerifiedProfile } from "./aiApprovals";

export const PHARMACY_TABLES = [
  "phm_categories", "phm_brands", "phm_drugs", "phm_suppliers", "phm_purchase_orders", "phm_purchase_order_items",
  "phm_stock_receipts", "phm_batches", "phm_stock", "phm_stock_movements", "phm_stock_transfers", "phm_stock_adjustments",
  "phm_dispense", "phm_dispense_items", "phm_controlled_medicine_register", "phm_sales", "phm_sale_items", "phm_payments",
  "phm_returns", "phm_return_items", "phm_insurance_claims", "phm_notifications", "phm_audit_logs",
] as const;

type PharmacyTable = (typeof PHARMACY_TABLES)[number];
type PharmacyRow = Record<string, any> & { data: Record<string, any> };
const pharmacyTableSchema = z.enum(PHARMACY_TABLES);
const idSchema = z.string().uuid();
const text = z.string().trim().min(1).max(240);
const optionalText = z.string().trim().max(2_000).optional().default("");
const money = z.number().finite().min(0).max(10_000_000_000);
const quantity = z.number().finite().positive().max(1_000_000);
const now = () => new Date().toISOString();

const adminRoles = new Set(["Super Administrator", "Organization Owner", "CEO", "Clinic Administrator", "Pharmacy Manager"]);
const groupForRole: Record<string, readonly string[]> = {
  "Pharmacy Manager": ["admin", "pharmacist", "procurement", "cashier", "finance"],
  Pharmacist: ["pharmacist"], "Pharmacy Technician": ["technician"],
  "Inventory Manager": ["procurement"], "Procurement Officer": ["procurement"],
  Cashier: ["cashier"], "Billing Officer": ["cashier", "finance"], "Finance Manager": ["finance"], CFO: ["finance"],
  Doctor: ["clinical"], Nurse: ["clinical"],
};

type PharmacyAction = "read" | "catalog" | "purchase" | "stock" | "dispense" | "controlled" | "sale" | "finance" | "governance";
const permissions: Record<PharmacyAction, readonly string[]> = {
  read: ["admin", "pharmacist", "technician", "procurement", "cashier", "finance", "clinical"],
  catalog: ["admin", "pharmacist"], purchase: ["admin", "pharmacist", "procurement"], stock: ["admin", "pharmacist", "technician", "procurement"],
  dispense: ["admin", "pharmacist", "technician"], controlled: ["admin", "pharmacist"], sale: ["admin", "pharmacist", "cashier"],
  finance: ["admin", "finance", "cashier"], governance: ["admin", "pharmacist", "finance"],
};

export function pharmacyAccessForRole(role: string) {
  const canonicalRole = canonicalVerifiedRole(role);
  const groups = groupForRole[canonicalRole] ?? [];
  const can = (action: PharmacyAction) => adminRoles.has(canonicalRole) || permissions[action].some((group) => groups.includes(group));
  return { role: canonicalRole, canRead: can("read"), canCatalog: can("catalog"), canPurchase: can("purchase"), canStock: can("stock"), canDispense: can("dispense"), canControlled: can("controlled"), canSale: can("sale"), canFinance: can("finance"), canGovern: can("governance") };
}

function ensure(role: string, action: PharmacyAction) {
  const access = pharmacyAccessForRole(role);
  const allowed: Record<PharmacyAction, boolean> = { read: access.canRead, catalog: access.canCatalog, purchase: access.canPurchase, stock: access.canStock, dispense: access.canDispense, controlled: access.canControlled, sale: access.canSale, finance: access.canFinance, governance: access.canGovern };
  if (!allowed[action]) throw new TRPCError({ code: "FORBIDDEN", message: "Your assigned pharmacy role does not allow this action." });
  return access;
}

function endpoint(table: PharmacyTable, params = new URLSearchParams()) { return `${ENV.supabaseUrl.replace(/\/$/, "")}/rest/v1/${table}?${params.toString()}`; }
async function request<T>(table: PharmacyTable, token: string, params = new URLSearchParams(), init: RequestInit = {}) {
  if (!ENV.supabaseUrl || !ENV.supabaseAnonKey) throw new TRPCError({ code: "PRECONDITION_FAILED", message: "Pharmacy data services are not configured." });
  const response = await fetch(endpoint(table, params), { ...init, headers: { apikey: ENV.supabaseAnonKey, authorization: `Bearer ${token}`, "content-type": "application/json", ...(init.headers || {}) } });
  const body = await response.json().catch(() => null) as T | { message?: string; details?: string } | null;
  if (!response.ok) {
    if (response.status === 401) throw new TRPCError({ code: "UNAUTHORIZED", message: "Your workspace session could not be verified." });
    if (response.status === 403) throw new TRPCError({ code: "FORBIDDEN", message: "This pharmacy record is not available to your workspace." });
    if (response.status === 409) throw new TRPCError({ code: "CONFLICT", message: "A pharmacy record changed before your request completed. Refresh and try again." });
    throw new TRPCError({ code: "BAD_REQUEST", message: "The pharmacy record could not be saved. Check the required fields and try again." });
  }
  return body as T;
}

function rowData(row: Record<string, unknown>): PharmacyRow { const data = row.data && typeof row.data === "object" && !Array.isArray(row.data) ? row.data as Record<string, any> : {}; return { ...data, ...row, data } as PharmacyRow; }
function params(companyId: string, id?: string) { const value = new URLSearchParams({ select: "*", company_id: `eq.${companyId}` }); if (id) value.set("id", `eq.${id}`); return value; }
async function rows(table: PharmacyTable, token: string, companyId: string, limit = 250): Promise<PharmacyRow[]> { const query = params(companyId); query.set("order", "created_at.desc"); query.set("limit", String(limit)); return (await request<Record<string, unknown>[]>(table, token, query)).map(rowData); }
async function row(table: PharmacyTable, token: string, companyId: string, id: string): Promise<PharmacyRow> { const query = params(companyId, id); query.set("limit", "1"); const value = (await request<Record<string, unknown>[]>(table, token, query))[0]; if (!value) throw new TRPCError({ code: "NOT_FOUND", message: "The pharmacy record is unavailable in this workspace." }); return rowData(value); }
async function insert(table: PharmacyTable, token: string, companyId: string, record: { name: string; status: string; amount?: number | null; notes?: string | null; data?: Record<string, unknown> }) {
  const payload = { company_id: companyId, name: record.name, status: record.status, amount: record.amount ?? null, notes: record.notes ?? null, data: record.data ?? {} };
  const value = (await request<Record<string, unknown>[]>(table, token, new URLSearchParams(), { method: "POST", headers: { Prefer: "return=representation" }, body: JSON.stringify(payload) }))[0];
  if (!value) throw new TRPCError({ code: "INTERNAL_SERVER_ERROR", message: "The pharmacy change could not be confirmed." });
  return rowData(value);
}
async function update(table: PharmacyTable, token: string, companyId: string, id: string, patch: { name?: string; status?: string; amount?: number | null; notes?: string | null; data?: Record<string, unknown> }) {
  const prior = await row(table, token, companyId, id); const query = params(companyId, id);
  const payload = { ...(patch.name === undefined ? {} : { name: patch.name }), ...(patch.status === undefined ? {} : { status: patch.status }), ...(patch.amount === undefined ? {} : { amount: patch.amount }), ...(patch.notes === undefined ? {} : { notes: patch.notes }), ...(patch.data === undefined ? {} : { data: { ...(prior.data as Record<string, unknown>), ...patch.data } }) };
  const value = (await request<Record<string, unknown>[]>(table, token, query, { method: "PATCH", headers: { Prefer: "return=representation" }, body: JSON.stringify(payload) }))[0];
  if (!value) throw new TRPCError({ code: "NOT_FOUND", message: "The pharmacy record is unavailable in this workspace." }); return rowData(value);
}
async function audit(token: string, companyId: string, actor: { id: string; full_name: string | null }, action: string, entity: string, recordId: string, details = "") { return insert("phm_audit_logs", token, companyId, { name: action, status: "Recorded", notes: details || null, data: { action, entity, recordId, actorId: actor.id, actorName: actor.full_name || "Workspace user", recordedAt: now() } }); }
async function notice(token: string, companyId: string, name: string, severity: string, data: Record<string, unknown>) { return insert("phm_notifications", token, companyId, { name, status: "Unread", data: { ...data, severity, createdAt: now() } }); }
async function context(req: CreateExpressContextOptions["req"], action: PharmacyAction) { const { profile, token } = await resolveVerifiedProfile(req); return { profile, token, access: ensure(profile.role, action) }; }

export const pharmacyListInput = z.object({ table: pharmacyTableSchema, search: z.string().trim().max(120).optional(), limit: z.number().int().min(1).max(500).default(250) });
export const pharmacyIdInput = z.object({ id: idSchema });
export const pharmacyMedicineInput = z.object({ name: text, genericName: optionalText, categoryId: idSchema.optional(), brandId: idSchema.optional(), form: text, strength: optionalText, barcode: z.string().trim().max(160).optional().default(""), sellingPrice: money, unitCost: money, reorderLevel: z.number().finite().min(0).max(1_000_000), requiresPrescription: z.boolean().default(false), controlled: z.boolean().default(false), taxRate: z.number().finite().min(0).max(100).default(0), notes: optionalText });
export const pharmacySupplierInput = z.object({ name: text, contactName: optionalText, phone: optionalText, email: z.string().trim().email().max(320).or(z.literal("")).default(""), address: optionalText, paymentTermsDays: z.number().int().min(0).max(365).default(30), notes: optionalText });
export const pharmacyCategoryInput = z.object({ name: text, notes: optionalText });
export const pharmacyBrandInput = z.object({ name: text, manufacturer: optionalText, notes: optionalText });
const purchaseItem = z.object({ drugId: idSchema, quantity: quantity, unitCost: money, taxRate: z.number().finite().min(0).max(100).default(0) });
export const pharmacyPurchaseOrderInput = z.object({ supplierId: idSchema, expectedDate: z.string().datetime().optional(), notes: optionalText, items: z.array(purchaseItem).min(1).max(100) });
export const pharmacyReceiptInput = z.object({ purchaseOrderId: idSchema.optional(), supplierId: idSchema, invoiceReference: text, receivedAt: z.string().datetime().optional(), notes: optionalText, items: z.array(z.object({ drugId: idSchema, quantity: quantity, unitCost: money, batchNumber: text, expiryDate: z.string().date(), barcode: z.string().trim().max(160).optional().default(""), warehouse: optionalText })).min(1).max(100) });
export const pharmacyAdjustmentInput = z.object({ batchId: idSchema, quantityDelta: z.number().finite().refine((value) => value !== 0, "Enter a non-zero adjustment quantity."), reason: text, notes: optionalText });
export const pharmacyTransferInput = z.object({ batchId: idSchema, quantity: quantity, fromLocation: text, toLocation: text, notes: optionalText });
const dispenseLine = z.object({ drugId: idSchema, quantity: quantity, instructions: optionalText });
export const pharmacyDispenseInput = z.object({ patientId: idSchema, prescriptionId: idSchema.optional(), prescriberName: text, prescriberLicense: optionalText, notes: optionalText, items: z.array(dispenseLine).min(1).max(50) });
export const pharmacySaleInput = z.object({ patientId: idSchema.optional(), customerName: optionalText, paymentMethod: z.enum(["Cash", "Mobile money", "Card", "Insurance", "Credit"]), insuranceProvider: optionalText, discount: money.default(0), notes: optionalText, items: z.array(z.object({ drugId: idSchema, quantity: quantity })).min(1).max(50) });
export const pharmacyReturnInput = z.object({ saleId: idSchema, reason: text, condition: z.enum(["Sealed and resellable", "Damaged", "Expired", "Unknown"]), notes: optionalText, items: z.array(z.object({ saleItemId: idSchema, quantity: quantity })).min(1).max(50) });
export const pharmacyMedicineUpdateInput = pharmacyMedicineInput.extend({ id: idSchema });
export const pharmacySupplierUpdateInput = pharmacySupplierInput.extend({ id: idSchema });
export const pharmacyCategoryUpdateInput = pharmacyCategoryInput.extend({ id: idSchema });
export const pharmacyBrandUpdateInput = pharmacyBrandInput.extend({ id: idSchema });
export const pharmacyArchiveInput = z.object({ table: z.enum(["phm_categories", "phm_brands", "phm_drugs", "phm_suppliers"]), id: idSchema, reason: optionalText });
export const pharmacyPaymentInput = z.object({ saleId: idSchema, amount: money.refine((value) => value > 0, "Enter a settlement amount greater than zero."), method: z.enum(["Cash", "Mobile money", "Card", "Bank transfer", "Insurance"]), insuranceProvider: optionalText, reference: optionalText, notes: optionalText });
export const pharmacySupplierPaymentInput = z.object({ supplierId: idSchema, amount: money.refine((value) => value > 0, "Enter a settlement amount greater than zero."), method: z.enum(["Cash", "Mobile money", "Card", "Bank transfer"]), reference: optionalText, notes: optionalText });
export const pharmacyInsuranceClaimInput = z.object({ saleId: idSchema, provider: text, memberReference: optionalText, amount: money.refine((value) => value > 0, "Enter a claim amount greater than zero."), notes: optionalText });
export const pharmacyNotificationInput = z.object({ id: idSchema });
export const pharmacyClinicalQueueInput = z.object({ search: z.string().trim().max(120).optional(), limit: z.number().int().min(1).max(250).default(100) });

export async function getPharmacyAccess(req: CreateExpressContextOptions["req"]) { const { profile } = await resolveVerifiedProfile(req); return pharmacyAccessForRole(profile.role); }
export async function listPharmacyRecords(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyListInput>) { const { profile, token, access } = await context(req, "read"); const records = await rows(input.table, token, profile.company_id, input.limit); const needle = input.search?.toLocaleLowerCase(); return { access, records: needle ? records.filter((record) => JSON.stringify(record).toLocaleLowerCase().includes(needle)) : records }; }
export async function createPharmacyCategory(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyCategoryInput>) { const { profile, token } = await context(req, "catalog"); const category = await insert("phm_categories", token, profile.company_id, { name: input.name, status: "Active", notes: input.notes || null, data: { createdAt: now() } }); await audit(token, profile.company_id, profile, "Pharmacy category created", "phm_categories", String(category.id)); return category; }
export async function createPharmacyBrand(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyBrandInput>) { const { profile, token } = await context(req, "catalog"); const brand = await insert("phm_brands", token, profile.company_id, { name: input.name, status: "Active", notes: input.notes || null, data: { manufacturer: input.manufacturer, createdAt: now() } }); await audit(token, profile.company_id, profile, "Pharmacy brand created", "phm_brands", String(brand.id)); return brand; }
export async function createPharmacySupplier(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacySupplierInput>) { const { profile, token } = await context(req, "purchase"); const supplier = await insert("phm_suppliers", token, profile.company_id, { name: input.name, status: "Active", notes: input.notes || null, data: { contactName: input.contactName, phone: input.phone, email: input.email, address: input.address, paymentTermsDays: input.paymentTermsDays, outstandingBalance: 0, createdAt: now() } }); await audit(token, profile.company_id, profile, "Pharmacy supplier created", "phm_suppliers", String(supplier.id)); return supplier; }
export async function createPharmacyMedicine(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyMedicineInput>) { const { profile, token } = await context(req, "catalog"); if (input.categoryId) await row("phm_categories", token, profile.company_id, input.categoryId); if (input.brandId) await row("phm_brands", token, profile.company_id, input.brandId); const medicine = await insert("phm_drugs", token, profile.company_id, { name: input.name, status: "Active", amount: input.sellingPrice, notes: input.notes || null, data: { ...input, createdAt: now(), availableQuantity: 0 } }); await audit(token, profile.company_id, profile, "Medicine catalogued", "phm_drugs", String(medicine.id), input.controlled ? "Controlled medicine flag enabled." : ""); return medicine; }
export async function updatePharmacyMedicine(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyMedicineUpdateInput>) { const { profile, token } = await context(req, "catalog"); if (input.categoryId) await row("phm_categories", token, profile.company_id, input.categoryId); if (input.brandId) await row("phm_brands", token, profile.company_id, input.brandId); const medicine = await update("phm_drugs", token, profile.company_id, input.id, { name: input.name, amount: input.sellingPrice, notes: input.notes || null, data: { genericName: input.genericName, categoryId: input.categoryId || null, brandId: input.brandId || null, form: input.form, strength: input.strength, barcode: input.barcode, sellingPrice: input.sellingPrice, unitCost: input.unitCost, reorderLevel: input.reorderLevel, requiresPrescription: input.requiresPrescription, controlled: input.controlled, taxRate: input.taxRate, updatedAt: now() } }); await audit(token, profile.company_id, profile, "Medicine catalogue updated", "phm_drugs", String(medicine.id)); return medicine; }
export async function updatePharmacySupplier(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacySupplierUpdateInput>) { const { profile, token } = await context(req, "purchase"); const supplier = await update("phm_suppliers", token, profile.company_id, input.id, { name: input.name, notes: input.notes || null, data: { contactName: input.contactName, phone: input.phone, email: input.email, address: input.address, paymentTermsDays: input.paymentTermsDays, updatedAt: now() } }); await audit(token, profile.company_id, profile, "Pharmacy supplier updated", "phm_suppliers", String(supplier.id)); return supplier; }
export async function updatePharmacyCategory(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyCategoryUpdateInput>) { const { profile, token } = await context(req, "catalog"); const category = await update("phm_categories", token, profile.company_id, input.id, { name: input.name, notes: input.notes || null, data: { updatedAt: now() } }); await audit(token, profile.company_id, profile, "Pharmacy category updated", "phm_categories", String(category.id)); return category; }
export async function updatePharmacyBrand(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyBrandUpdateInput>) { const { profile, token } = await context(req, "catalog"); const brand = await update("phm_brands", token, profile.company_id, input.id, { name: input.name, notes: input.notes || null, data: { manufacturer: input.manufacturer, updatedAt: now() } }); await audit(token, profile.company_id, profile, "Pharmacy brand updated", "phm_brands", String(brand.id)); return brand; }
export async function archivePharmacyRecord(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyArchiveInput>) { const action: PharmacyAction = input.table === "phm_suppliers" ? "purchase" : "catalog"; const { profile, token } = await context(req, action); const record = await row(input.table, token, profile.company_id, input.id); if (input.table === "phm_drugs" && Number(record.availableQuantity || 0) > 0) throw new TRPCError({ code: "PRECONDITION_FAILED", message: "A medicine with available stock cannot be archived. Transfer, adjust, or dispense its stock first." }); const archived = await update(input.table, token, profile.company_id, input.id, { status: "Archived", data: { archivedAt: now(), archiveReason: input.reason || "Archived by pharmacy user" } }); await audit(token, profile.company_id, profile, "Pharmacy record archived", input.table, String(archived.id), input.reason); return archived; }
export async function createPharmacyPurchaseOrder(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyPurchaseOrderInput>) { const { profile, token } = await context(req, "purchase"); const supplier = await row("phm_suppliers", token, profile.company_id, input.supplierId); const items = await Promise.all(input.items.map(async (item) => ({ ...item, drug: await row("phm_drugs", token, profile.company_id, item.drugId) }))); const subtotal = items.reduce((sum, item) => sum + item.quantity * item.unitCost, 0); const taxAmount = items.reduce((sum, item) => sum + item.quantity * item.unitCost * item.taxRate / 100, 0); const orderNo = `PO-${new Date().getFullYear()}-${Date.now().toString().slice(-6)}`; const order = await insert("phm_purchase_orders", token, profile.company_id, { name: orderNo, status: "Draft", amount: subtotal + taxAmount, notes: input.notes || null, data: { orderNo, supplierId: input.supplierId, supplierName: supplier.name, expectedDate: input.expectedDate || null, subtotal, taxAmount, total: subtotal + taxAmount, createdAt: now() } }); for (const item of items) await insert("phm_purchase_order_items", token, profile.company_id, { name: `${orderNo} · ${item.drug.name}`, status: "Ordered", amount: item.quantity * item.unitCost, data: { purchaseOrderId: order.id, drugId: item.drugId, drugName: item.drug.name, quantityOrdered: item.quantity, quantityReceived: 0, unitCost: item.unitCost, taxRate: item.taxRate } }); await audit(token, profile.company_id, profile, "Purchase order created", "phm_purchase_orders", String(order.id)); return order; }

export async function receivePharmacyStock(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyReceiptInput>) { const { profile, token } = await context(req, "stock"); const supplier = await row("phm_suppliers", token, profile.company_id, input.supplierId); if (input.purchaseOrderId) await row("phm_purchase_orders", token, profile.company_id, input.purchaseOrderId); const prepared = await Promise.all(input.items.map(async (item) => ({ ...item, drug: await row("phm_drugs", token, profile.company_id, item.drugId) }))); const receivedAt = input.receivedAt || now(); const total = prepared.reduce((sum, item) => sum + item.quantity * item.unitCost, 0); const receiptNo = `GRN-${new Date().getFullYear()}-${Date.now().toString().slice(-6)}`; const receipt = await insert("phm_stock_receipts", token, profile.company_id, { name: receiptNo, status: "Received", amount: total, notes: input.notes || null, data: { receiptNo, purchaseOrderId: input.purchaseOrderId || null, supplierId: supplier.id, supplierName: supplier.name, invoiceReference: input.invoiceReference, receivedAt, total } }); for (const item of prepared) { const expiry = new Date(`${item.expiryDate}T23:59:59.999Z`); if (expiry.getTime() <= Date.now()) throw new TRPCError({ code: "BAD_REQUEST", message: `${item.drug.name} cannot be received with an expired batch.` }); const batch = await insert("phm_batches", token, profile.company_id, { name: `${item.drug.name} · ${item.batchNumber}`, status: "Active", amount: item.quantity * item.unitCost, data: { receiptId: receipt.id, drugId: item.drugId, drugName: item.drug.name, batchNumber: item.batchNumber, expiryDate: item.expiryDate, quantityOnHand: item.quantity, unitCost: item.unitCost, barcode: item.barcode || item.drug.barcode || "", warehouse: item.warehouse || "Main pharmacy", receivedAt } }); await insert("phm_stock", token, profile.company_id, { name: `${item.drug.name} · ${item.batchNumber}`, status: "Available", amount: item.quantity * item.unitCost, data: { batchId: batch.id, drugId: item.drugId, drugName: item.drug.name, batchNumber: item.batchNumber, quantity: item.quantity, reorderLevel: item.drug.reorderLevel ?? 0, expiryDate: item.expiryDate, unitCost: item.unitCost, warehouse: item.warehouse || "Main pharmacy" } }); await insert("phm_stock_movements", token, profile.company_id, { name: `Receipt · ${item.drug.name}`, status: "Posted", amount: item.quantity * item.unitCost, data: { movementType: "Receipt", batchId: batch.id, drugId: item.drugId, drugName: item.drug.name, quantityDelta: item.quantity, quantityAfter: item.quantity, referenceType: "phm_stock_receipts", referenceId: receipt.id, occurredAt: receivedAt } }); await update("phm_drugs", token, profile.company_id, item.drugId, { data: { availableQuantity: Number(item.drug.availableQuantity || 0) + item.quantity, lastReceivedAt: receivedAt } }); } await update("phm_suppliers", token, profile.company_id, supplier.id, { data: { outstandingBalance: Number(supplier.outstandingBalance || 0) + total, lastReceiptAt: receivedAt } }); await audit(token, profile.company_id, profile, "Stock receipt posted", "phm_stock_receipts", String(receipt.id)); return receipt; }

export async function adjustPharmacyStock(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyAdjustmentInput>) { const { profile, token } = await context(req, "stock"); const batch = await row("phm_batches", token, profile.company_id, input.batchId); const next = Number(batch.quantityOnHand || 0) + input.quantityDelta; if (next < 0) throw new TRPCError({ code: "BAD_REQUEST", message: "The adjustment would make this batch quantity negative." }); const adjustment = await insert("phm_stock_adjustments", token, profile.company_id, { name: `Stock adjustment · ${batch.drugName || batch.name}`, status: "Posted", amount: Math.abs(input.quantityDelta) * Number(batch.unitCost || 0), notes: input.reason, data: { batchId: batch.id, drugId: batch.drugId, quantityDelta: input.quantityDelta, reason: input.reason, adjustedAt: now() } }); await update("phm_batches", token, profile.company_id, String(batch.id), { status: next === 0 ? "Depleted" : String(batch.status), amount: next * Number(batch.unitCost || 0), data: { quantityOnHand: next } }); await insert("phm_stock_movements", token, profile.company_id, { name: `Adjustment · ${batch.drugName || batch.name}`, status: "Posted", amount: Math.abs(input.quantityDelta) * Number(batch.unitCost || 0), notes: input.notes || null, data: { movementType: "Adjustment", batchId: batch.id, drugId: batch.drugId, quantityDelta: input.quantityDelta, quantityAfter: next, referenceType: "phm_stock_adjustments", referenceId: adjustment.id, occurredAt: now() } }); await audit(token, profile.company_id, profile, "Stock adjustment posted", "phm_stock_adjustments", String(adjustment.id), input.reason); return adjustment; }
export async function createPharmacyTransfer(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyTransferInput>) { const { profile, token } = await context(req, "stock"); const batch = await row("phm_batches", token, profile.company_id, input.batchId); if (Number(batch.quantityOnHand || 0) < input.quantity) throw new TRPCError({ code: "BAD_REQUEST", message: "Insufficient available batch stock for this transfer." }); const transfer = await insert("phm_stock_transfers", token, profile.company_id, { name: `Transfer · ${batch.drugName || batch.name}`, status: "Requested", amount: input.quantity * Number(batch.unitCost || 0), notes: input.notes || null, data: { batchId: batch.id, drugId: batch.drugId, quantity: input.quantity, fromLocation: input.fromLocation, toLocation: input.toLocation, requestedAt: now() } }); await audit(token, profile.company_id, profile, "Stock transfer requested", "phm_stock_transfers", String(transfer.id)); return transfer; }

async function patientExists(token: string, companyId: string, patientId: string) { const url = `${ENV.supabaseUrl.replace(/\/$/, "")}/rest/v1/hc_patients?select=id,name&company_id=eq.${companyId}&id=eq.${patientId}&limit=1`; const response = await fetch(url, { headers: { apikey: ENV.supabaseAnonKey, authorization: `Bearer ${token}` } }); const records = await response.json().catch(() => []); if (!response.ok || !Array.isArray(records) || !records[0]) throw new TRPCError({ code: "NOT_FOUND", message: "The selected patient is unavailable in this workspace." }); return records[0] as { id: string; name: string } }
async function allocate(token: string, companyId: string, drug: PharmacyRow, qty: number, referenceType: string, referenceId: string) { const candidates = (await rows("phm_batches", token, companyId, 500)).filter((batch) => batch.drugId === drug.id && batch.status === "Active" && Number(batch.quantityOnHand || 0) > 0 && String(batch.expiryDate || "") >= new Date().toISOString().slice(0, 10)).sort((a, b) => String(a.expiryDate).localeCompare(String(b.expiryDate))); let remaining = qty; const allocations: PharmacyRow[] = []; for (const batch of candidates) { if (!remaining) break; const issued = Math.min(remaining, Number(batch.quantityOnHand)); const after = Number(batch.quantityOnHand) - issued; await update("phm_batches", token, companyId, String(batch.id), { status: after === 0 ? "Depleted" : "Active", amount: after * Number(batch.unitCost || 0), data: { quantityOnHand: after } }); await insert("phm_stock_movements", token, companyId, { name: `${referenceType} · ${drug.name}`, status: "Posted", amount: issued * Number(batch.unitCost || 0), data: { movementType: referenceType, batchId: batch.id, drugId: drug.id, quantityDelta: -issued, quantityAfter: after, referenceType, referenceId, occurredAt: now() } }); allocations.push({ ...batch, issued }); remaining -= issued; } if (remaining) throw new TRPCError({ code: "BAD_REQUEST", message: `${drug.name} has insufficient eligible, unexpired stock.` }); await update("phm_drugs", token, companyId, String(drug.id), { data: { availableQuantity: Math.max(0, Number(drug.availableQuantity || 0) - qty) } }); return allocations; }
export async function dispensePharmacyPrescription(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyDispenseInput>) { const { profile, token, access } = await context(req, "dispense"); const patient = await patientExists(token, profile.company_id, input.patientId); const validated = await Promise.all(input.items.map(async (item) => ({ ...item, drug: await row("phm_drugs", token, profile.company_id, item.drugId) }))); for (const item of validated) { if (item.drug.controlled && !access.canControlled) throw new TRPCError({ code: "FORBIDDEN", message: "Only a Pharmacist or pharmacy administrator may issue controlled medicines." }); if ((item.drug.requiresPrescription || item.drug.controlled) && !input.prescriptionId) throw new TRPCError({ code: "BAD_REQUEST", message: `${item.drug.name} requires a valid prescription reference before dispensing.` }); }
  const total = validated.reduce((sum, item) => sum + Number(item.drug.sellingPrice || item.drug.amount || 0) * item.quantity, 0); const dispenseNo = `DSP-${Date.now().toString().slice(-8)}`; const dispense = await insert("phm_dispense", token, profile.company_id, { name: dispenseNo, status: "Dispensed", amount: total, notes: input.notes || null, data: { dispenseNo, patientId: patient.id, patientName: patient.name, prescriptionId: input.prescriptionId || null, prescriberName: input.prescriberName, dispensedAt: now(), total } }); for (const item of validated) { const allocations = await allocate(token, profile.company_id, item.drug, item.quantity, "Dispense", String(dispense.id)); await insert("phm_dispense_items", token, profile.company_id, { name: `${dispenseNo} · ${item.drug.name}`, status: "Dispensed", amount: Number(item.drug.sellingPrice || item.drug.amount || 0) * item.quantity, notes: item.instructions || null, data: { dispenseId: dispense.id, drugId: item.drug.id, drugName: item.drug.name, quantity: item.quantity, instructions: item.instructions, allocations: allocations.map((batch) => ({ batchId: batch.id, batchNumber: batch.batchNumber, quantity: batch.issued })) } }); if (item.drug.controlled) await insert("phm_controlled_medicine_register", token, profile.company_id, { name: `${dispenseNo} · ${item.drug.name}`, status: "Issued", amount: item.quantity, notes: input.prescriberLicense || "Prescriber licence not recorded", data: { dispenseId: dispense.id, patientId: patient.id, prescriptionId: input.prescriptionId, drugId: item.drug.id, quantity: item.quantity, prescriberName: input.prescriberName, issuedById: profile.id, issuedAt: now() } }); } if (input.prescriptionId) { try { await markHealthcarePrescriptionDispensed(token, profile.company_id, input.prescriptionId, profile); } catch (error) { await notice(token, profile.company_id, "Clinical prescription handoff requires review", "Warning", { dispenseId: dispense.id, prescriptionId: input.prescriptionId, reason: "The dispensing record was posted, but the linked prescription status was not updated." }); } } await audit(token, profile.company_id, profile, "Prescription dispensed", "phm_dispense", String(dispense.id)); return dispense; }
export async function completePharmacySale(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacySaleInput>) { const { profile, token } = await context(req, "sale"); if (input.patientId) await patientExists(token, profile.company_id, input.patientId); const items = await Promise.all(input.items.map(async (item) => ({ ...item, drug: await row("phm_drugs", token, profile.company_id, item.drugId) }))); if (items.some((item) => item.drug.requiresPrescription || item.drug.controlled)) throw new TRPCError({ code: "BAD_REQUEST", message: "Prescription-only or controlled medicines must be issued through the prescription dispensing workflow." }); const subtotal = items.reduce((sum, item) => sum + Number(item.drug.sellingPrice || item.drug.amount || 0) * item.quantity, 0); const taxable = items.reduce((sum, item) => sum + Number(item.drug.sellingPrice || item.drug.amount || 0) * item.quantity * Number(item.drug.taxRate || 0) / 100, 0); if (input.discount > subtotal + taxable) throw new TRPCError({ code: "BAD_REQUEST", message: "Discount cannot exceed the sale total." }); const total = subtotal + taxable - input.discount; const receiptNo = `PHR-${Date.now().toString().slice(-8)}`; const sale = await insert("phm_sales", token, profile.company_id, { name: receiptNo, status: input.paymentMethod === "Credit" || input.paymentMethod === "Insurance" ? "Awaiting settlement" : "Paid", amount: total, notes: input.notes || null, data: { receiptNo, saleDate: now(), patientId: input.patientId || null, customerName: input.customerName || "Walk-in customer", paymentMethod: input.paymentMethod, insuranceProvider: input.insuranceProvider || null, subtotal, taxAmount: taxable, discount: input.discount, total } }); for (const item of items) { const allocations = await allocate(token, profile.company_id, item.drug, item.quantity, "Sale", String(sale.id)); await insert("phm_sale_items", token, profile.company_id, { name: `${receiptNo} · ${item.drug.name}`, status: "Sold", amount: Number(item.drug.sellingPrice || item.drug.amount || 0) * item.quantity, data: { saleId: sale.id, drugId: item.drug.id, drugName: item.drug.name, quantity: item.quantity, unitPrice: Number(item.drug.sellingPrice || item.drug.amount || 0), allocations: allocations.map((batch) => ({ batchId: batch.id, quantity: batch.issued })) } }); } if (input.paymentMethod !== "Credit" && input.paymentMethod !== "Insurance") await insert("phm_payments", token, profile.company_id, { name: `Payment · ${receiptNo}`, status: "Recorded", amount: total, data: { saleId: sale.id, receiptNo, method: input.paymentMethod, paidAt: now() } }); await audit(token, profile.company_id, profile, "Pharmacy sale completed", "phm_sales", String(sale.id)); return sale; }

export async function recordPharmacySalePayment(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyPaymentInput>) { const { profile, token } = await context(req, "finance"); const sale = await row("phm_sales", token, profile.company_id, input.saleId); const payments = (await rows("phm_payments", token, profile.company_id, 500)).filter((payment) => payment.saleId === sale.id); const paid = payments.reduce((sum, payment) => sum + Number(payment.amount || 0), 0); const balance = Math.max(0, Number(sale.total || sale.amount || 0) - paid); if (input.amount > balance + 0.0001) throw new TRPCError({ code: "BAD_REQUEST", message: "The settlement amount exceeds the remaining sale balance." }); const payment = await insert("phm_payments", token, profile.company_id, { name: `Settlement · ${sale.receiptNo || sale.name}`, status: "Recorded", amount: input.amount, notes: input.notes || null, data: { saleId: sale.id, receiptNo: sale.receiptNo || sale.name, method: input.method, insuranceProvider: input.insuranceProvider || null, reference: input.reference || null, paidAt: now() } }); const nextBalance = Math.max(0, balance - input.amount); await update("phm_sales", token, profile.company_id, String(sale.id), { status: nextBalance === 0 ? "Paid" : "Awaiting settlement", data: { paidAmount: paid + input.amount, balance: nextBalance, settledAt: nextBalance === 0 ? now() : null } }); await audit(token, profile.company_id, profile, "Pharmacy sale settlement recorded", "phm_payments", String(payment.id)); return { payment, saleId: sale.id, balance: nextBalance }; }
export async function recordPharmacySupplierPayment(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacySupplierPaymentInput>) { const { profile, token } = await context(req, "finance"); const supplier = await row("phm_suppliers", token, profile.company_id, input.supplierId); const balance = Number(supplier.outstandingBalance || 0); if (input.amount > balance + 0.0001) throw new TRPCError({ code: "BAD_REQUEST", message: "The settlement amount exceeds the supplier balance." }); const payment = await insert("phm_payments", token, profile.company_id, { name: `Supplier settlement · ${supplier.name}`, status: "Recorded", amount: input.amount, notes: input.notes || null, data: { supplierId: supplier.id, supplierName: supplier.name, method: input.method, reference: input.reference || null, paidAt: now() } }); const nextBalance = Math.max(0, balance - input.amount); await update("phm_suppliers", token, profile.company_id, String(supplier.id), { data: { outstandingBalance: nextBalance, lastSettlementAt: now() } }); await audit(token, profile.company_id, profile, "Supplier settlement recorded", "phm_payments", String(payment.id)); return { payment, supplierId: supplier.id, balance: nextBalance }; }
export async function createPharmacyInsuranceClaim(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyInsuranceClaimInput>) { const { profile, token } = await context(req, "finance"); const sale = await row("phm_sales", token, profile.company_id, input.saleId); const outstanding = Math.max(0, Number(sale.total || sale.amount || 0) - Number(sale.paidAmount || 0)); if (input.amount > outstanding + 0.0001) throw new TRPCError({ code: "BAD_REQUEST", message: "The claim amount exceeds the unsettled sale balance." }); const claimNo = `PHM-CLM-${Date.now().toString().slice(-8)}`; const claim = await insert("phm_insurance_claims", token, profile.company_id, { name: claimNo, status: "Submitted", amount: input.amount, notes: input.notes || null, data: { claimNo, saleId: sale.id, receiptNo: sale.receiptNo || sale.name, provider: input.provider, memberReference: input.memberReference || null, submittedAt: now(), requestedAmount: input.amount } }); await update("phm_sales", token, profile.company_id, String(sale.id), { status: "Awaiting insurer", data: { insuranceProvider: input.provider, insuranceClaimId: claim.id } }); await audit(token, profile.company_id, profile, "Pharmacy insurance claim submitted", "phm_insurance_claims", String(claim.id)); return claim; }
export async function returnPharmacySaleItems(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyReturnInput>) { const { profile, token } = await context(req, "sale"); const sale = await row("phm_sales", token, profile.company_id, input.saleId); const saleItems = await Promise.all(input.items.map(async (item) => ({ ...item, saleItem: await row("phm_sale_items", token, profile.company_id, item.saleItemId) }))); for (const item of saleItems) { if (item.saleItem.saleId !== sale.id) throw new TRPCError({ code: "FORBIDDEN", message: "A return line must belong to the selected sale." }); const returned = Number(item.saleItem.returnedQuantity || 0); if (item.quantity + returned > Number(item.saleItem.quantity || 0)) throw new TRPCError({ code: "BAD_REQUEST", message: "The return quantity exceeds the original sale quantity." }); }
  const returnNo = `RTN-${Date.now().toString().slice(-8)}`; const total = saleItems.reduce((sum, item) => sum + item.quantity * Number(item.saleItem.unitPrice || 0), 0); const restockable = input.condition === "Sealed and resellable"; const returnRecord = await insert("phm_returns", token, profile.company_id, { name: returnNo, status: restockable ? "Restocked" : "Quarantined", amount: total, notes: input.notes || null, data: { returnNo, saleId: sale.id, receiptNo: sale.receiptNo || sale.name, reason: input.reason, condition: input.condition, returnedAt: now(), total } });
  for (const item of saleItems) { const drug = await row("phm_drugs", token, profile.company_id, String(item.saleItem.drugId)); const allocations = Array.isArray(item.saleItem.allocations) ? item.saleItem.allocations as Array<Record<string, unknown>> : []; if (restockable) { let remaining = item.quantity; for (const allocation of allocations) { if (!remaining) break; const allocatedQty = Number(allocation.quantity || 0); if (!allocatedQty) continue; const batchId = String(allocation.batchId || ""); if (!batchId) continue; const batch = await row("phm_batches", token, profile.company_id, batchId); if (String(batch.expiryDate || "") < new Date().toISOString().slice(0, 10)) continue; const returnedQty = Math.min(remaining, allocatedQty); const after = Number(batch.quantityOnHand || 0) + returnedQty; await update("phm_batches", token, profile.company_id, String(batch.id), { status: "Active", amount: after * Number(batch.unitCost || 0), data: { quantityOnHand: after } }); await insert("phm_stock_movements", token, profile.company_id, { name: `Return · ${drug.name}`, status: "Posted", amount: returnedQty * Number(batch.unitCost || 0), data: { movementType: "Return", batchId: batch.id, drugId: drug.id, quantityDelta: returnedQty, quantityAfter: after, referenceType: "phm_returns", referenceId: returnRecord.id, occurredAt: now() } }); remaining -= returnedQty; } if (remaining) await notice(token, profile.company_id, "Return requires stock review", "Warning", { returnId: returnRecord.id, drugId: drug.id, quantity: remaining, reason: "No eligible original batch remained for restock." }); await update("phm_drugs", token, profile.company_id, String(drug.id), { data: { availableQuantity: Number(drug.availableQuantity || 0) + item.quantity } }); }
    await update("phm_sale_items", token, profile.company_id, String(item.saleItem.id), { data: { returnedQuantity: Number(item.saleItem.returnedQuantity || 0) + item.quantity, lastReturnId: returnRecord.id } }); await insert("phm_return_items", token, profile.company_id, { name: `${returnNo} · ${drug.name}`, status: restockable ? "Restocked" : "Quarantined", amount: item.quantity * Number(item.saleItem.unitPrice || 0), data: { returnId: returnRecord.id, saleItemId: item.saleItem.id, drugId: drug.id, drugName: drug.name, quantity: item.quantity, condition: input.condition, restocked: restockable } }); }
  await update("phm_sales", token, profile.company_id, String(sale.id), { data: { returnedAmount: Number(sale.returnedAmount || 0) + total, returnBalance: total } }); await audit(token, profile.company_id, profile, "Pharmacy sale return recorded", "phm_returns", String(returnRecord.id), input.reason); return returnRecord; }

async function healthcareRows(table: "hc_patients" | "hc_prescriptions", token: string, companyId: string, limit: number) { const url = `${ENV.supabaseUrl.replace(/\/$/, "")}/rest/v1/${table}?select=*&company_id=eq.${companyId}&limit=${limit}&order=created_at.desc`; const response = await fetch(url, { headers: { apikey: ENV.supabaseAnonKey, authorization: `Bearer ${token}` } }); const body = await response.json().catch(() => []); if (!response.ok || !Array.isArray(body)) throw new TRPCError({ code: "BAD_REQUEST", message: "Clinical references are temporarily unavailable. No pharmacy records were changed." }); return body.map(rowData); }
async function markHealthcarePrescriptionDispensed(token: string, companyId: string, prescriptionId: string, profile: { id: string; full_name: string | null }) { const url = `${ENV.supabaseUrl.replace(/\/$/, "")}/rest/v1/hc_prescriptions?select=*&company_id=eq.${companyId}&id=eq.${prescriptionId}&limit=1`; const response = await fetch(url, { headers: { apikey: ENV.supabaseAnonKey, authorization: `Bearer ${token}`, "content-type": "application/json" } }); const source = (await response.json().catch(() => [])) as Record<string, unknown>[]; if (!response.ok || !source[0]) throw new TRPCError({ code: "NOT_FOUND", message: "The linked prescription is unavailable in this workspace." }); const prescription = rowData(source[0]); const patch = await fetch(`${ENV.supabaseUrl.replace(/\/$/, "")}/rest/v1/hc_prescriptions?company_id=eq.${companyId}&id=eq.${prescriptionId}`, { method: "PATCH", headers: { apikey: ENV.supabaseAnonKey, authorization: `Bearer ${token}`, "content-type": "application/json", Prefer: "return=representation" }, body: JSON.stringify({ status: "Dispensed", data: { ...prescription.data, dispensedAt: now(), dispensedBy: profile.full_name || "Pharmacy user" } }) }); if (!patch.ok) throw new TRPCError({ code: "BAD_REQUEST", message: "The linked Healthcare prescription could not be updated after dispensing." }); }
export async function getPharmacyClinicalQueue(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyClinicalQueueInput>) { const { profile, token } = await context(req, "dispense"); const [patients, prescriptions] = await Promise.all([healthcareRows("hc_patients", token, profile.company_id, input.limit), healthcareRows("hc_prescriptions", token, profile.company_id, input.limit)]); const needle = input.search?.toLocaleLowerCase(); const pending = prescriptions.filter((record) => /pending|partial/i.test(String(record.status))).map((record) => ({ id: record.id, name: record.name, status: record.status, patientId: record.patientId, patientName: record.patientName, doctorName: record.doctorName, issuedAt: record.issuedAt, medications: record.medications, instructions: record.instructions })).filter((record) => !needle || JSON.stringify(record).toLocaleLowerCase().includes(needle)); return { patients: patients.map((patient) => ({ id: patient.id, name: patient.name, mrn: patient.mrn || patient.patientNumber || "" })).filter((patient) => !needle || `${patient.name} ${patient.mrn}`.toLocaleLowerCase().includes(needle)), prescriptions: pending }; }
export async function markPharmacyNotificationRead(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyNotificationInput>) { const { profile, token } = await context(req, "read"); return update("phm_notifications", token, profile.company_id, input.id, { status: "Read", data: { readAt: now(), readBy: profile.id } }); }
export async function listPharmacyAudit(req: CreateExpressContextOptions["req"], input: z.infer<typeof pharmacyListInput>) { const { profile, token } = await context(req, "governance"); const records = await rows("phm_audit_logs", token, profile.company_id, input.limit); const needle = input.search?.toLocaleLowerCase(); return needle ? records.filter((record) => JSON.stringify(record).toLocaleLowerCase().includes(needle)) : records; }
export async function getPharmacyReports(req: CreateExpressContextOptions["req"]) { const { profile, token } = await context(req, "read"); const [drugs, batches, sales, payments, suppliers, controlled, movements, returns, claims] = await Promise.all([rows("phm_drugs", token, profile.company_id), rows("phm_batches", token, profile.company_id), rows("phm_sales", token, profile.company_id), rows("phm_payments", token, profile.company_id), rows("phm_suppliers", token, profile.company_id), rows("phm_controlled_medicine_register", token, profile.company_id), rows("phm_stock_movements", token, profile.company_id), rows("phm_returns", token, profile.company_id), rows("phm_insurance_claims", token, profile.company_id)]); const activeBatches = batches.filter((batch) => batch.status === "Active"); const stockValue = activeBatches.reduce((sum, batch) => sum + Number(batch.quantityOnHand || 0) * Number(batch.unitCost || 0), 0); const receivables = sales.reduce((sum, sale) => sum + Math.max(0, Number(sale.total || sale.amount || 0) - Number(sale.paidAmount || 0)), 0); return { stock: { skuCount: drugs.length, activeBatchCount: activeBatches.length, stockValue, movements: movements.length }, finance: { salesTotal: sales.reduce((sum, sale) => sum + Number(sale.amount || 0), 0), cashReceived: payments.filter((payment) => !payment.supplierId).reduce((sum, payment) => sum + Number(payment.amount || 0), 0), supplierBalance: suppliers.reduce((sum, supplier) => sum + Number(supplier.outstandingBalance || 0), 0), receivables, returnValue: returns.reduce((sum, record) => sum + Number(record.amount || 0), 0) }, compliance: { controlledIssues: controlled.length, insuranceClaims: claims.length, claimsOutstanding: claims.filter((claim) => !/paid|approved/i.test(String(claim.status))).reduce((sum, claim) => sum + Number(claim.amount || 0), 0) } }; }

export async function getPharmacyDashboard(req: CreateExpressContextOptions["req"]) { const { profile, token, access } = await context(req, "read"); const [drugs, batches, sales, dispense, notifications, suppliers, prescriptions] = await Promise.all([rows("phm_drugs", token, profile.company_id), rows("phm_batches", token, profile.company_id), rows("phm_sales", token, profile.company_id), rows("phm_dispense", token, profile.company_id), rows("phm_notifications", token, profile.company_id), rows("phm_suppliers", token, profile.company_id), healthcareRows("hc_prescriptions", token, profile.company_id, 250).catch(() => [])]); const today = new Date().toISOString().slice(0, 10); const expiry90 = new Date(Date.now() + 90 * 86_400_000).toISOString().slice(0, 10); const activeBatches = batches.filter((batch) => ["Active", "Available"].includes(String(batch.status))); const totalStockValue = activeBatches.reduce((sum, batch) => sum + Number(batch.quantityOnHand || 0) * Number(batch.unitCost || 0), 0); const lowStock = drugs.filter((drug) => Number(drug.availableQuantity || 0) <= Number(drug.reorderLevel || 0)); const expiring = activeBatches.filter((batch) => String(batch.expiryDate || "") <= expiry90); return { access, totals: { medicines: drugs.length, activeBatches: activeBatches.length, stockValue: totalStockValue, lowStock: lowStock.length, expiring: expiring.length, todaySales: sales.filter((sale) => String(sale.saleDate || "").slice(0, 10) === today).reduce((sum, sale) => sum + Number(sale.amount || 0), 0), pendingDispenses: prescriptions.filter((record) => /pending|partial/i.test(String(record.status))).length || dispense.filter((record) => /pending|partial/i.test(String(record.status))).length, supplierBalance: suppliers.reduce((sum, supplier) => sum + Number(supplier.outstandingBalance || 0), 0) }, lowStock: lowStock.slice(0, 20), expiring: expiring.sort((a, b) => String(a.expiryDate).localeCompare(String(b.expiryDate))).slice(0, 20), notifications: notifications.filter((item) => item.status !== "Read").slice(0, 20) };
}
